// 1. Initialize Firecord for Spigot or Standalone mode
Firecord.init(NodeType.SPIGOT);

// 2. Define a shared object extending AbstractObject
public final class PlayerData extends AbstractObject {
    // Synchronized fields using R-types (or primitives woven by AspectJ)
    private RInteger level = new RInteger(new Bytes("level"));
    private RString rank = new RString(new Bytes("rank"));

    public PlayerData(Bytes key) {
        super(key);
    }
}

// 3. Load or create the object from the distributed memory
PlayerData data = (PlayerData) AbstractData.create(new Bytes("player-123"));

// 4. Modify fields - changes are automatically woven and broadcasted to other nodes
data.getLevel().set(100);
